def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    seeds=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg]
    out=[[bg]*W for _ in range(H)]
    mid=(W-1)//2
    def pat(d,tr):  # d: horizontal distance from seed col (absolute parity matters), tr: row distance
        return (d%2==0 and tr%2==0) or (d%2==0 and d>tr and tr%2==1) or (d%2==1 and d<tr)
    tops=[s for s in seeds if s[0]<H/2]
    bots=[s for s in seeds if s[0]>=H/2]
    # build top-band pattern per row: relative cols 0..mid, colored by nearest same-side top seed color
    tb=[[bg]*(mid+1) for _ in range(H//2)]
    for r,c,col in tops:
        for rr in range(r,H//2):
            tr=rr-r
            for cc in range(mid+1):
                d=abs(cc-c)
                if pat(d,tr): tb[rr-r][cc]=col
    for rr in range(H//2):
        for cc in range(mid+1):
            col=None
            # search left-half columns for a non-bg cell; color = seed at that column? demo: seed cols were edges
            for mcol in range(mid+1):
                colc=tb[rr][mcol]
                if colc!=bg:
                    # find which top seed owns column mcol
                    for sr,sc,scol in tops:
                        if sc==mcol:
                            col=scol; break
                    out[rr][cc]=col; break
            else: continue
            if out[rr][cc]==bg: pass
    # right half: mirror of left via c -> W-1-c; pattern symmetric anyway since pat depends on |d|... but parities differ
    for rr in range(H//2):
        for cc in range(mid+1,W):
            dc=cc-(mid+1)   # 0-indexed distance from midline into right half
            for ml in range(mid+1):
                if tb[rr][ml]!=bg:
                    col=None
                    for sr,sc,scol in tops:
                        if sc==ml: col=scol; break
                    if col is not None:
                        out[rr][cc]=col; break
    # bottom band: vertical mirror using bot seeds
    tb_b=[[bg]*(mid+1) for _ in range(H-H//2)]
    for r,c,col in bots:
        nb=H-r
        for rr in range(nb):
            tr=nb-1-rr
            for cc in range(mid+1):
                d=abs(cc-c)
                if pat(d,tr): tb_b[rr][cc]=col
    for rr in range(H-H//2):
        for cc in range(mid+1):
            col=None
            for ml in range(mid+1):
                colc=tb_b[rr][ml]
                if colc!=bg:
                    for sr,sc,scol in bots:
                        if sc==ml: col=scol; break
                    out[H-H//2+rr][cc]=col; break
    for rr in range(H-H//2):
        for cc in range(mid+1,W):
            for ml in range(mid+1):
                colc=tb_b[rr][ml]
                if colc!=bg:
                    for sr,sc,scol in bots:
                        if sc==ml: col=scol; break
                    out[H-H//2+rr][cc]=col; break
    return out

